package com.learnagent.workspace;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/workspaces")public class WorkspaceController{private final WorkspaceService service;public WorkspaceController(WorkspaceService service){this.service=service;}@PostMapping public ResponseEntity<WorkspaceService.ProjectView>create(@RequestBody WorkspaceService.CreateRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(request));}@GetMapping public List<WorkspaceService.ProjectView>list(){return service.list();}@GetMapping("/{id}")public WorkspaceService.ProjectView get(@PathVariable UUID id){return service.get(id);}@PostMapping("/{id}/generate")public WorkspaceService.ProjectView generate(@PathVariable UUID id){return service.generate(id);}@PostMapping("/{id}/build")public WorkspaceService.BuildResult build(@PathVariable UUID id,@RequestParam(defaultValue="test")String goal){return service.build(id,goal);}@PostMapping("/{id}/open-folder")public WorkspaceService.OpenFolderResult openFolder(@PathVariable UUID id){return service.openFolder(id);}@GetMapping("/{id}/tree")public List<WorkspaceService.TreeEntry>tree(@PathVariable UUID id){return service.tree(id);}@GetMapping("/{id}/files")public WorkspaceService.FileView read(@PathVariable UUID id,@RequestParam String path){return service.read(id,path);}@PutMapping("/{id}/files")public WorkspaceService.FileView write(@PathVariable UUID id,@RequestParam String path,@RequestBody WorkspaceService.FileWrite body){return service.write(id,path,body.content());}@GetMapping("/{id}/artifacts")public List<WorkspaceArtifact>artifacts(@PathVariable UUID id){return service.artifactList(id);}}
